      "hauteur_maximale": {
        "valeur": "non règlementée pour les bâtiments agricoles ; 12 mètres max pour les bâtiments à usage d'habitation et leurs extensions ; 4,5 mètres max pour les annexes aux habitations",
        "condition": "Pour les bâtiments agricoles : pas de hauteur réglementée mais rapport d'échelle à maintenir avec l'environnement notamment à proximité des villages et hameaux. Pour les habitations : hauteur max 12 m. Pour les annexes : 4,5 m.",
        "page_source": "112"
      },
      "emprise_au_sol": {
        "valeur": "pas de reglementation",
        "condition": "L'emprise au sol n'est pas réglementée en zone A (hors secteur Ah où elle ne peut excéder 30% de la superficie du terrain).",
        "page_source": "113"
      },
      "implantation_voies": {
        "regle": "Les constructions nouvelles doivent être implantées à une distance minimale de 3 mètres en retrait de l'alignement des voies publiques ou privées ouvertes à la circulation automobile.",
        "page_source": "111"
      },
      "implantation_limites": {
        "regle": "Les nouvelles constructions doivent être implantées en retrait des limites séparatives, avec un recul minimum de 3 mètres.",
        "page_source": "112"
      },
      "stationnement": {
        "regle": "Se référer aux dispositions générales. Pour les destinations 'Autres activités des secteurs secondaire ou tertiaire' (industrie, entrepôt, bureau) : le nombre de places est déterminé en fonction des besoins (salariés, visiteurs, transports en commun, mutualisation possible).",
        "valeur_pl": "non precisee",
        "valeur_vl": "non precisee",
        "page_source": "28-30"
      },
      "espaces_verts": {
        "regle": "Le caractère bocager doit être sauvegardé. Les talus avec leur végétation bordant les voies ainsi que ceux existant sur les limites séparatives doivent être préservés. Les espaces boisés classés à conserver sont soumis au régime de l'article L.113-1. Les haies bocagères, chemins, talus et parcelles boisées identifiés au plan de zonage sont protégés. Les plantations existantes d'essences locales doivent être conservées.",
        "page_source": "114"
      },
      "destinations": {
        "autorisees": [
          "Exploitation agricole et forestière (bâtiments agricoles, constructions liées au stockage et entretien du matériel agricole)",
          "Logements de fonction (un seul nouveau par exploitation, second loge de gardiennage possible si emprise max 30 m²)",
          "Diversification des activités agricoles (sous réserve que les activités restent accessoires, respectent la réciprocité, ne favorisent pas la dispersion de l'urbanisation)",
          "Constructions et équipements de production d'énergies renouvelables (méthanisation, agri-photovoltaïque, photovoltaïque en toiture, trackers solaires, éoliennes sous réserve réglementaire)",
          "Changement de destination de bâtiments existants (sous conditions : emprise au sol min 60 m², intégrité du bâtiment, intérêt architectural, avis conforme CDPENAF)",
          "Abris pour animaux non liés à une activité agricole professionnelle (matériaux naturels, démontables, pleine terre, emprise max 40 m²)",
          "Extensions et annexes des constructions à destination d'habitation existantes (extension limitée à 50 m² ou 30% de la surface existante, annexes dans un rayon de 30 m, emprise cumulée max 50 m²)",
          "Constructions et installations d'intérêt collectif et équipements publics (sous réserve de bonne intégration paysagère)",
          "En secteur Az : extensions de bâtiments existants (limitées à 300 m² d'emprise au sol) et nouvelles constructions à destination d'activités économiques (limitées à 200 m² d'emprise au sol cumulée)"
        ],
        "interdites": [
          "Toutes les occupations et utilisations du sol non mentionnées dans les dispositions générales ou autorisées sous conditions",
          "Les constructions portant atteinte au développement des activités agricoles ou à l'environnement",
          "Les constructions ne respectant pas les conditions de distances réglementaires"
        ],
        "page_source": "107-111"
      },
      "contraintes_particulieres": [
        {
          "description": "Recul de 15 mètres à partir des berges des cours d'eau non recouverts pour les constructions nouvelles (hors zone U et AU), sauf exceptions (captage, ponts, quais, ouvrages hydrauliques, etc.)",
          "page_source": "19"
        },
        {
          "description": "En secteur Az (STECAL à vocation d'activités économiques) : les nouvelles constructions à destination d'activités économiques sont limitées à 200 m² d'emprise au sol cumulée ; les extensions de bâtiments existants limitées à 300 m² d'emprise au sol. L'implantation doit favoriser un regroupement autour des constructions existantes.",
          "page_source": "111"
        },
        {
          "description": "Les constructions et installations d'intérêt collectif ne doivent pas être incompatibles avec l'exercice d'une activité agricole, pastorale ou forestière et ne pas porter atteinte à la sauvegarde des espaces naturels et des paysages.",
          "page_source": "107"
        },
        {
          "description": "Le changement de destination en zone A est soumis à l'avis conforme de la Commission Départementale de la Préservation des Espaces Agricoles, Naturels et Forestiers (CDPENAF).",
          "page_source": "109"
        },
        {
          "description": "Les unités de méthanisation doivent ne pas engendrer de nuisances par rapport aux habitations existantes ni générer de nuisances liées aux circulations et aux accès.",
          "page_source": "108"
        },
        {
          "description": "Les installations photovoltaïques en toiture sont autorisées sous réserve que le bâtiment soit nécessaire à l'exploitation, fermé sur au moins 2 côtés et implanté à moins de 150 mètres du site d'exploitation.",
          "page_source": "108"
        },
        {
          "description": "Le logement de fonction doit être intégré ou accolé au bâtiment d'exploitation, ou en cas d'impossibilité architecturale démontrée, implanté dans un rayon de 100 m maximum du bâtiment d'exploitation agricole.",
          "page_source": "108"
        },
        {
          "description": "Les bâtiments agricoles doivent présenter une unité architecturale sur toutes les faces ; les teintes doivent favoriser l'insertion dans la zone (teintes neutres privilégiées).",
          "page_source": "114"
        },
        {
          "description": "Les clôtures ne doivent pas dépasser 1,50 mètre sur la voie et autres emprises publiques et 2 mètres en limites séparatives. Les clôtures en plaques ciments sont interdites en limite sur voie ou espace public.",
          "page_source": "114"
        }
      ]
    }
  ],
  "alertes": []
}

